// XL: this comparison is an optional fence-wrapper reuse optimization.
// Missing APIs keep the real OpenSharedFence/OpenSharedHandle path available.
bool CompareObjectHandlesIfAvailable(HANDLE first, HANDLE second) {
    if (first == second) return true;
    using Compare = BOOL(WINAPI*)(HANDLE, HANDLE);
    static const Compare compare = [] {
        HMODULE module = GetModuleHandleW(L"kernelbase.dll");
        if (!module) module = GetModuleHandleW(L"kernel32.dll");
        return module ? reinterpret_cast<Compare>(GetProcAddress(module, "CompareObjectHandles"))
                      : nullptr;
    }();
    return compare && compare(first, second);
}

